# Surah Al-Hashr (chapter 59) — part 2: ayat 13-24 (IDs 5139-5150)
SURAH = 59

ENTRIES = {
5139: (
"بے شک تم ان کے دلوں میں اللہ سے زیادہ ڈرانے والے ہو — یہ اس لیے کہ وہ ایسی قوم ہیں جو نہیں سمجھتے",
"""۱۔ ان کے دلوں میں رعب — لأنتم أشد رهبۃ في صدورهم من الله؛ ذلک بأنهم قوم لا یفقهون۔
۲۔ ’’لَأَنتُمْ أَشَدُّ رَهْبَۃً فِي صُدُورِهِم مِّنَ اللَّهِ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌ لَّا يَفْقَهُونَ‘‘ — بے شک تم ان کے دلوں میں اللہ سے زیادہ ڈرانے والے ہو — یہ اس لیے کہ وہ ایسی قوم ہیں جو نہیں سمجھتے — یعنی بے شک تم ان کے دلوں میں اللہ سے زیادہ ڈرانے والے ہو یہ اس لیے کہ وہ ایسی قوم ہیں جو نہیں سمجھتے۔
۳۔ عملی سبق: اللہ سے ڈرتے رہو؛ خوفِ خدا اختیار کرو۔"""
),
5140: (
"وہ تم سے اکٹھے جنگ نہیں کریں گے مگر قلعوں والے شہروں میں یا دیواروں کے پیچھے — ان میں باہمی سخت بغض ہے — تم انہیں اکٹھے گمان کرتے ہو حالانکہ ان کے دل منتشر ہیں — یہ اس لیے کہ وہ ایسی قوم ہیں جو نہیں سوچتے",
"""۱۔ ان کی کمزوری — لا یقاتلونکم جمیعًا إلا في قری محصنۃ أو من وراء جدر؛ بأسهم بینهم شدید؛ تحسبهم جمیعًا و قلوبهم شتّی؛ ذلک بأنهم قوم لا یعقلون۔
۲۔ ’’لَا يُقَاتِلُونَكُمْ جَمِيعًا إِلَّا فِي قُرًى مُّحَصَّنَۃٍ أَوْ مِن وَرَاءِ جُدُرٍ بَأْسُهُم بَيْنَهُمْ شَدِيدٌ تَحْسَبُهُمْ جَمِيعًا وَقُلُوبُهُمْ شَتَّىٰ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌ لَّا يَعْقِلُونَ‘‘ — وہ تم سے اکٹھے جنگ نہیں کریں گے مگر قلعوں والے شہروں میں یا دیواروں کے پیچھے — ان میں باہمی سخت بغض ہے — تم انہیں اکٹھے گمان کرتے ہو حالانکہ ان کے دل منتشر ہیں — یہ اس لیے کہ وہ ایسی قوم ہیں جو نہیں سوچتے — یعنی وہ تم سے اکٹھے جنگ نہیں کریں گے مگر قلعوں والے شہروں میں یا دیواروں کے پیچھے ان میں باہمی سخت بغض ہے تم انہیں اکٹھے گمان کرتے ہو حالانکہ ان کے دل منتشر ہیں یہ اس لیے کہ وہ ایسی قوم ہیں جو نہیں سوچتے۔
۳۔ عملی سبق: اللہ کی مدد پر بھروسہ رکھو؛ اللہ سے ڈرو۔"""
),
5141: (
"جیسے ان سے پہلے والے ابھی قریب ہی — انہوں نے اپنے کام کا بُرا انجام چکھا — اور ان کے لیے دردناک عذاب ہے",
"""۱۔ پہلوں کا انجام — کمثل الذین من قبلهم قریبا؛ ذاقوا وبال أمرهم؛ و لهم عذاب الیم۔
۲۔ ’’كَمَثَلِ الَّذِينَ مِن قَبْلِهِمْ قَرِيبًا ذَاقُوا وَبَالَ أَمْرِهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ‘‘ — جیسے ان سے پہلے والے ابھی قریب ہی — انہوں نے اپنے کام کا بُرا انجام چکھا — اور ان کے لیے دردناک عذاب ہے — یعنی جیسے ان سے پہلے والے ابھی قریب ہی انہوں نے اپنے کام کا بُرا انجام چکھا اور ان کے لیے دردناک عذاب ہے۔
۳۔ عملی سبق: گناہ چھوڑو؛ اللہ سے ڈرو۔"""
),
5142: (
"جیسے شیطان کہ اس نے انسان سے کہا کفر کر — پس جب اس نے کفر کیا تو کہا میں تجھ سے بری ہوں — میں اللہ رب العالمین سے ڈرتا ہوں",
"""۱۔ شیطان کا دھوکا — کمثل الشیطان إذ قال للإنسان اکفر؛ فلما کفر قال إني بريء منک؛ إني أخاف الله رب العالمین۔
۲۔ ’’كَمَثَلِ الشَّيْطَانِ إِذْ قَالَ لِلْإِنسَانِ اكْفُرْ فَلَمَّا كَفَرَ قَالَ إِنِّي بَرِيءٌ مِّنكَ إِنِّي أَخَافُ اللَّهَ رَبَّ الْعَالَمِينَ‘‘ — جیسے شیطان کہ اس نے انسان سے کہا کفر کر — پس جب اس نے کفر کیا تو کہا میں تجھ سے بری ہوں — میں اللہ رب العالمین سے ڈرتا ہوں — یعنی جیسے شیطان کہ اس نے انسان سے کہا کفر کر پس جب اس نے کفر کیا تو کہا میں تجھ سے بری ہوں میں اللہ رب العالمین سے ڈرتا ہوں۔
۳۔ عملی سبق: شیطان کے دھوکے سے بچو؛ اللہ سے ڈرو۔"""
),
5143: (
"پس ان دونوں کا انجام یہ ہوا کہ وہ آگ میں ہمیشہ رہیں گے — اور یہی ظالموں کا بدلہ ہے",
"""۱۔ انجام — فکان عاقبتهما أنهما في النار خالدین فیها؛ و ذلک جزاء الظالمین۔
۲۔ ’’فَكَانَ عَاقِبَتَهُمَا أَنَّهُمَا فِي النَّارِ خَالِدَيْنِ فِيهَا وَذَٰلِكَ جَزَاءُ الظَّالِمِينَ‘‘ — پس ان دونوں کا انجام یہ ہوا کہ وہ آگ میں ہمیشہ رہیں گے — اور یہی ظالموں کا بدلہ ہے — یعنی پس ان دونوں کا انجام یہ ہوا کہ وہ آگ میں ہمیشہ رہیں گے اور یہی ظالموں کا بدلہ ہے۔
۳۔ عملی سبق: ظلم سے بچو؛ اللہ سے ڈرو۔"""
),
5144: (
"اے ایمان والو اللہ سے ڈرو — اور ہر شخص دیکھے کہ اس نے کل کے لیے کیا بھیجا — اور اللہ سے ڈرو — بے شک اللہ جو تم کرتے ہو اس سے باخبر ہے",
"""۱۔ کل کے لیے عمل — یا أیها الذین آمنوا اتقوا الله ولتنظر نفس ما قدّمت لغد؛ و اتقوا الله؛ إن الله خبیر بما تعملون۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَلْتَنظُرْ نَفْسٌ مَّا قَدَّمَتْ لِغَدٍ وَاتَّقُوا اللَّهَ إِنَّ اللَّهَ خَبِيرٌ بِمَا تَعْمَلُونَ‘‘ — اے ایمان والو اللہ سے ڈرو — اور ہر شخص دیکھے کہ اس نے کل کے لیے کیا بھیجا — اور اللہ سے ڈرو — بے شک اللہ جو تم کرتے ہو اس سے باخبر ہے — یعنی اے ایمان والو اللہ سے ڈرو اور ہر شخص دیکھے کہ اس نے کل کے لیے کیا بھیجا اور اللہ سے ڈرو بے شک اللہ جو تم کرتے ہو اس سے باخبر ہے۔
۳۔ عملی سبق: آخرت کے لیے عمل کرو؛ اللہ سے ڈرو۔"""
),
5145: (
"اور ان جیسے نہ ہو جاؤ جنہوں نے اللہ کو بھلا دیا پس اللہ نے انہیں اپنے آپ کو بُھلوا دیا — یہی فاسق ہیں",
"""۱۔ اللہ کو بھولنا — و لا تکونوا کالذین نسوا الله فأنساهم أنفسهم؛ أولئک هم الفاسقون۔
۲۔ ’’وَلَا تَكُونُوا كَالَّذِينَ نَسُوا اللَّهَ فَأَنسَاهُمْ أَنفُسَهُمْ أُولَٰئِكَ هُمُ الْفَاسِقُونَ‘‘ — اور ان جیسے نہ ہو جاؤ جنہوں نے اللہ کو بھلا دیا پس اللہ نے انہیں اپنے آپ کو بُھلوا دیا — یہی فاسق ہیں — یعنی اور ان جیسے نہ ہو جاؤ جنہوں نے اللہ کو بھلا دیا پس اللہ نے انہیں اپنے آپ کو بُھلوا دیا یہی فاسق ہیں۔
۳۔ عملی سبق: اللہ کا ذکر کرو؛ اللہ سے ڈرو۔"""
),
5146: (
"آگ والے اور جنت والے برابر نہیں — جنت والے ہی کامیاب ہیں",
"""۱۔ دونوں برابر نہیں — لا یستوي أصحاب النار و أصحاب الجنة؛ أصحاب الجنة هم الفائزون۔
۲۔ ’’لَا يَسْتَوِي أَصْحَابُ النَّارِ وَأَصْحَابُ الْجَنَّۃِ أَصْحَابُ الْجَنَّۃِ هُمُ الْفَائِزُونَ‘‘ — آگ والے اور جنت والے برابر نہیں — جنت والے ہی کامیاب ہیں — یعنی آگ والے اور جنت والے برابر نہیں جنت والے ہی کامیاب ہیں۔
۳۔ عملی سبق: جنت کی طلب کرو؛ اللہ سے ڈرو۔"""
),
5147: (
"اگر ہم یہ قرآن کسی پہاڑ پر نازل کرتے تو اسے اللہ کے خوف سے جھکتا اور ریزہ ریزہ ہوتے ہوئے دیکھتا — اور یہ مثالیں ہم لوگوں کے لیے بیان کرتے ہیں تاکہ وہ سوچیں",
"""۱۔ قرآن کی عظمت — لو أنزلنا هذا القرآن علی جبل لرأیته خاشعًا متصدّعًا من خشیۃ الله؛ و تلک الأمثال نضربها للناس لعلهم یتفکرون۔
۲۔ ’’لَوْ أَنزَلْنَا هَٰذَا الْقُرْآنَ عَلَىٰ جَبَلٍ لَّرَأَيْتَهُ خَاشِعًا مُّتَصَدِّعًا مِّنْ خَشْيَۃِ اللَّهِ وَتِلْكَ الْأَمْثَالُ نَضْرِبُهَا لِلنَّاسِ لَعَلَّهُمْ يَتَفَكَّرُونَ‘‘ — اگر ہم یہ قرآن کسی پہاڑ پر نازل کرتے تو اسے اللہ کے خوف سے جھکتا اور ریزہ ریزہ ہوتے ہوئے دیکھتا — اور یہ مثالیں ہم لوگوں کے لیے بیان کرتے ہیں تاکہ وہ سوچیں — یعنی اگر ہم یہ قرآن کسی پہاڑ پر نازل کرتے تو اسے اللہ کے خوف سے جھکتا اور ریزہ ریزہ ہوتے ہوئے دیکھتا اور یہ مثالیں ہم لوگوں کے لیے بیان کرتے ہیں تاکہ وہ سوچیں۔
۳۔ عملی سبق: قرآن سے خوف کھاؤ؛ اللہ سے ڈرو۔"""
),
5148: (
"وہی اللہ ہے جس کے سوا کوئی معبود نہیں — غیب اور ظاہر کا جاننے والا — وہی رحمٰن رحیم ہے",
"""۱۔ اللہ — هو الله الذي لا إله إلا هو؛ عالم الغیب و الشهادۃ؛ هو الرحمٰن الرحیم۔
۲۔ ’’هُوَ اللَّهُ الَّذِي لَا إِلَٰهَ إِلَّا هُوَ عَالِمُ الْغَيْبِ وَالشَّهَادَۃِ هُوَ الرَّحْمَٰنُ الرَّحِيمُ‘‘ — وہی اللہ ہے جس کے سوا کوئی معبود نہیں — غیب اور ظاہر کا جاننے والا — وہی رحمٰن رحیم ہے — یعنی وہی اللہ ہے جس کے سوا کوئی معبود نہیں غیب اور ظاہر کا جاننے والا وہی رحمٰن رحیم ہے۔
۳۔ عملی سبق: اللہ واحد کو مانو؛ اللہ سے ڈرو۔"""
),
5149: (
"وہی اللہ ہے جس کے سوا کوئی معبود نہیں — بادشاہ قدوس سلام المؤمن المهيمن العزیز الجبار المتکبر — اللہ اس سے پاک ہے جو وہ شریک ٹھہراتے ہیں",
"""۱۔ اللہ کی صفات — هو الله الذي لا إله إلا هو؛ الملک القدوس السلام المؤمن المهیمن العزیز الجبار المتکبر؛ سبحان الله عما یشرکون۔
۲۔ ’’هُوَ اللَّهُ الَّذِي لَا إِلَٰهَ إِلَّا هُوَ الْمَلِكُ الْقُدُّوسُ السَّلَامُ الْمُؤْمِنُ الْمُهَيْمِنُ الْعَزِيزُ الْجَبَّارُ الْمُتَكَبِّرُ سُبْحَانَ اللَّهِ عَمَّا يُشْرِكُونَ‘‘ — وہی اللہ ہے جس کے سوا کوئی معبود نہیں — بادشاہ قدوس سلام المؤمن المهيمن العزیز الجبار المتکبر — اللہ اس سے پاک ہے جو وہ شریک ٹھہراتے ہیں — یعنی وہی اللہ ہے جس کے سوا کوئی معبود نہیں بادشاہ قدوس سلام المؤمن المهيمن العزیز الجبار المتکبر اللہ اس سے پاک ہے جو وہ شریک ٹھہراتے ہیں۔
۳۔ عملی سبق: شرک سے بچو؛ اللہ سے ڈرو۔"""
),
5150: (
"وہی اللہ خالق بارئ مصور — اسی کے لیے بہترین نام ہیں — اس کی تسبیح کرتا ہے جو آسمانوں اور زمین میں ہے — اور وہ غالب حکمت والا ہے",
"""۱۔ اللہ کے اسماء حسنہ — هو الله الخالق البارئ المصوّر؛ له الأسماء الحسنی؛ یسبّح له ما في السماوات و الأرض؛ و هو العزیز الحکیم۔
۲۔ ’’هُوَ اللَّهُ الْخَالِقُ الْبَارِئُ الْمُصَوِّرُ لَهُ الْأَسْمَاءُ الْحُسْنَىٰ يُسَبِّحُ لَهُ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ وَهُوَ الْعَزِيزُ الْحَكِيمُ‘‘ — وہی اللہ خالق بارئ مصور — اسی کے لیے بہترین نام ہیں — اس کی تسبیح کرتا ہے جو آسمانوں اور زمین میں ہے — اور وہ غالب حکمت والا ہے — یعنی وہی اللہ خالق بارئ مصور اسی کے لیے بہترین نام ہیں اس کی تسبیح کرتا ہے جو آسمانوں اور زمین میں ہے اور وہ غالب حکمت والا ہے۔
۳۔ عملی سبق: اللہ کے اسماء حسنہ یاد کرو؛ اللہ سے ڈرو۔"""
),
}
